function nest(index) {
  const out = {};
  for (const row of rows) {
    const parts = row[0].split(".");
    let cursor = out;
    for (let i = 0; i < parts.length - 1; i++) {
      cursor[parts[i]] ??= {};
      cursor = cursor[parts[i]];
    }
    cursor[parts.at(-1)] = row[index];
  }
  return out;
}

for (const [index, code] of [["1", "fr"], ["2", "en"], ["3", "de"], ["4", "es"]]) {
  writeFileSync(`messages/${code}.json`, `${JSON.stringify(nest(Number(index)), null, 2)}\n`);
}
